bash -lc 'set -e; if ! command -v aws >/dev/null 2>&1; then snap install aws-cli --classic; fi; export AZURE_KEY=$(aws ssm get-parameter --name /video-editing-agent/AZURE_AI_API_KEY --with-decryption --region us-east-1 --query Parameter.Value --output text); python3 - <<"PY"
from pathlib import Path
import os
path = Path("/opt/video-editing-agent/.env")
updates = {
    "AZURE_AI_ENDPOINT": "https://panastra.services.ai.azure.com/",
    "VIDEO_AGENT_DEFAULT_MODEL": "Kimi-K2.6-1",
    "AZURE_AI_API_KEY": os.environ["AZURE_KEY"],
}
lines = []
seen = set()
if path.exists():
    for raw in path.read_text(encoding="utf-8", errors="ignore").splitlines():
        if not raw.strip() or raw.lstrip().startswith("#") or "=" not in raw:
            lines.append(raw)
            continue
        key = raw.split("=", 1)[0]
        if key in updates:
            lines.append(f"{key}={updates[key]}")
            seen.add(key)
        else:
            lines.append(raw)
for key, value in updates.items():
    if key not in seen:
        lines.append(f"{key}={value}")
path.write_text("\n".join(lines) + "\n", encoding="utf-8")
PY
chown ubuntu:ubuntu /opt/video-editing-agent/.env; chmod 600 /opt/video-editing-agent/.env; systemctl restart video-editing-agent'
